import React, { useState } from "react";
import { Link } from "react-scroll";

const Header = () => {
  const [isOpen, setIsOpen] = useState(false);
  const toggleMenu = () => setIsOpen(!isOpen);

  const [darkmode, setdarkmode] = useState("light");

  const handledrClick = () => {
    if(darkmode == "light") {
      setdarkmode();
    }
    else {
      setdarkmode("light");
    }
  }

  const lighttheme = {
    backgroundColor: "#ecf0f3",
    color: ""
  }

  return (
    <header className="navbar sticky-top">
      <div className="container nav-container">
        <div className="nav-logo">MyPortfolio</div>

        <nav className={`nav-links ${isOpen ? "open" : ""}`}>
          <Link
            to="hero"
            smooth={true}
            duration={400}
            offset={-80}
            onClick={() => setIsOpen(false)}
          >
            Home
          </Link>
          <Link
            to="services"
            smooth={true}
            duration={400}
            offset={-60}
            onClick={() => setIsOpen(false)}
          >
            Services
          </Link>
          <Link
            to="projects"
            smooth={true}
            duration={400}
            offset={-60}
            onClick={() => setIsOpen(false)}
          >
            Projects
          </Link>
          <Link
            to="about"
            smooth={true}
            duration={400}
            offset={-60}
            onClick={() => setIsOpen(false)}
          >
            About
          </Link>
          <Link
            to="contact"
            smooth={true}
            duration={400}
            offset={-60}
            onClick={() => setIsOpen(false)}
          >
            Contact Us
          </Link>
        </nav>
        <div class="form-check form-switch">
          <input
            class="form-check-input"
            type="checkbox"
            role="switch"
            id="switchCheckDefault"
          />
          <label class="form-check-label" for="switchCheckDefault" mode={darkmode} onClick={handledrClick}>
            Dark Mode
          </label>
        </div>

        <div className="hamburger" onClick={toggleMenu}>
          <div className={`bar ${isOpen ? "open" : ""}`}></div>
          <div className={`bar ${isOpen ? "open" : ""}`}></div>
          <div className={`bar ${isOpen ? "open" : ""}`}></div>
        </div>
      </div>
    </header>
  );
};

export default Header;
